import{_ as l,a0 as p,w as r,s as o,ao as u,I as e,x as s,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Ubuntu 22.04 之 KVM 安裝手札 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 22.04 之 KVM 安裝手札 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 22.04 之 KVM 安裝手札 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 22.04 之 KVM 安裝手札 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220524 How to Install KVM on Ubuntu 22.04 -Jammy Jellyfish-","title":"Ubuntu 22.04 之 KVM 安裝手札","tag":"202206","desc":""},"relativePath":"202206/20220524 How to Install KVM on Ubuntu 22.04 -Jammy Jellyfish-.md","filePath":"[post].md"}'),c={name:"202206/20220524 How to Install KVM on Ubuntu 22.04 -Jammy Jellyfish-.md"};function d(h,a,g,b,k,m){const t=p("Link");return r(),o("div",null,[a[15]||(a[15]=u(`<h1 id="ubuntu-22-04-之-kvm-安裝手札" tabindex="-1">Ubuntu 22.04 之 KVM 安裝手札 <a class="header-anchor" href="#ubuntu-22-04-之-kvm-安裝手札" aria-label="Permalink to “Ubuntu 22.04 之 KVM 安裝手札”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/01/171619m6dd7bjb8292bbb9.jpg" alt=""></p><p><strong>KVM</strong> 是 <ruby>基於內核的虛擬機<rt>Kernel-based Virtual Machine</rt></ruby> 的首字母縮寫，這是一項集成在內核中的開源虛擬化技術。它是一種類型一（裸機）的<ruby>管理程序<rt>hypervisor</rt></ruby>，可以使內核能夠作為一個<ruby>裸機管理程序<rt>bare-metal hypervisor</rt></ruby>。</p><p>在 KVM 之上可以運行 Windows 和 Liunx 虛擬機。每個虛擬機都獨立於其它虛擬機和底層操作系統（宿主機系統），並擁有自己的 CPU、內存、網絡接口、存儲設備等計算資源。</p><p>本文將介紹在 Ubuntu 22.04 LTS（Jammy Jellyfish）中如何安裝 KVM 。在文末，我們也將演示如何在安裝 KVM 完成之後創建一台虛擬機。</p><h3 id="_1、更新-ubuntu-22-04" tabindex="-1">1、更新 Ubuntu 22.04 <a class="header-anchor" href="#_1、更新-ubuntu-22-04" aria-label="Permalink to “1、更新 Ubuntu 22.04”">​</a></h3><p>在一切開始前，打開終端並通過如下命令更新本地的軟件包索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><h3 id="_2、檢查虛擬化是否開啓" tabindex="-1">2、檢查虛擬化是否開啓 <a class="header-anchor" href="#_2、檢查虛擬化是否開啓" aria-label="Permalink to “2、檢查虛擬化是否開啓”">​</a></h3><p>在進一步行動之前，首先需要檢查你的 CPU 是否支持 KVM 虛擬化，確保你係統中有 VT-x（ vmx）英特爾處理器或 AMD-V（svm）處理器。</p><p>你可以通過運行如下命令，如果輸出值大於 0，那麼虛擬化被啓用。否則，虛擬化被禁用，你需要啓用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ egrep -c &#39;(vmx|svm)&#39; /proc/cpuinfo</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/SVM-VMX-Flags-Cpuinfo-linux.png" alt="SVM-VMX-Flags-Cpuinfo-linux"></p><p>根據上方命令輸出，你可以推斷出虛擬化功能已經啓用，因為輸出結果大於 0。如果虛擬化功能沒有啓用，請確保在系統的 BIOS 設置中啓用虛擬化功能。</p><p>另外，你可以通過如下命令判斷 KVM 虛擬化是否已經在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kvm-ok</span></span></code></pre></div><p>運行該命令之前，請確保你已經安裝了 <code>cpu-checker</code> 軟件包，否則將提示未找到該命令的報錯。</p><p>直接就在下面，你會得到如何解決這個問題的指示，那就是安裝 <code>cpu-checker</code> 包。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/KVM-OK-Command-Not-Found-Ubuntu.png" alt="KVM-OK-Command-Not-Found-Ubuntu"></p><p>隨後，通過如下命令安裝 <code>cpu-checker</code> 軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y cpu-checker</span></span></code></pre></div><p>接着再運行 <code>kvm-ok</code> 命令，如果 KVM 已經啓動，你將看到如下輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kvm-ok</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/KVM-OK-Command-Output.png" alt="KVM-OK-Command-Output"></p><h3 id="_3、在-ubuntu-22-04-上安裝-kvm" tabindex="-1">3、在 Ubuntu 22.04 上安裝 KVM <a class="header-anchor" href="#_3、在-ubuntu-22-04-上安裝-kvm" aria-label="Permalink to “3、在 Ubuntu 22.04 上安裝 KVM”">​</a></h3><p>隨後，通過如下命令在 Ubuntu 22.04 中安裝 KVM 以及其他相關虛擬化軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y qemu-kvm virt-manager libvirt-daemon-system virtinst libvirt-clients bridge-utils</span></span></code></pre></div><p>以下為你解釋剛剛安裝了哪些軟件包：</p><ul><li><code>qemu-kvm</code> – 一個提供硬件仿真的開源仿真器和虛擬化包</li><li><code>virt-manager</code> – 一款通過 libvirt 守護進程，基於 QT 的圖形界面的虛擬機管理工具</li><li><code>libvirt-daemon-system</code> – 為運行 libvirt 進程提供必要配置文件的工具</li><li><code>virtinst</code> – 一套為置備和修改虛擬機提供的命令列工具</li><li><code>libvirt-clients</code> – 一組客户端的庫和API，用於從命令列管理和控制虛擬機和管理程序</li><li><code>bridge-utils</code> – 一套用於創建和管理橋接設備的工具</li></ul><h3 id="_4、啓用虛擬化守護進程-libvirtd" tabindex="-1">4、啓用虛擬化守護進程（libvirtd） <a class="header-anchor" href="#_4、啓用虛擬化守護進程-libvirtd" aria-label="Permalink to “4、啓用虛擬化守護進程（libvirtd）”">​</a></h3><p>在所有軟件包安裝完畢之後，通過如下命令啓用並啓動 libvirt 守護進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now libvirtd</span></span>
<span class="line"><span>$ sudo systemctl start libvirtd</span></span></code></pre></div><p>你可以通過如下命令驗證該虛擬化守護進程是否已經運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status libvirtd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Libvirtd-Status-Ubuntu-Linux.png" alt="Libvirtd-Status-Ubuntu-Linux"></p><p>另外，請將當前登錄用户加入 <code>kvm</code> 和 <code>libvirt</code> 用户組，以便能夠創建和管理虛擬機。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG kvm $USER</span></span>
<span class="line"><span>$ sudo usermod -aG libvirt $USER</span></span></code></pre></div><p><code>$USER</code> 環境變量引用的即為當前登錄的用户名。你需要重新登錄才能使得配置生效。</p><h3 id="_5、創建網橋-br0" tabindex="-1">5、創建網橋（br0） <a class="header-anchor" href="#_5、創建網橋-br0" aria-label="Permalink to “5、創建網橋（br0）”">​</a></h3><p>如果你打算從本機（Ubuntu 22.04）之外訪問 KVM 虛擬機，你必須將虛擬機的網卡映射至網橋。<code>virbr0</code> 網橋是 KVM 安裝完成後自動創建的，僅做測試用途。</p><p>你可以通過如下內容在 <code>/etc/netplan</code> 目錄下創建文件 <code>01-netcfg.yaml</code> 來新建網橋：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/netplan/01-netcfg.yaml</span></span>
<span class="line"><span>network:</span></span>
<span class="line"><span>  ethernets:</span></span>
<span class="line"><span>    enp0s3:</span></span>
<span class="line"><span>      dhcp4: false</span></span>
<span class="line"><span>      dhcp6: false</span></span>
<span class="line"><span>  # add configuration for bridge interface</span></span>
<span class="line"><span>  bridges:</span></span>
<span class="line"><span>    br0:</span></span>
<span class="line"><span>      interfaces: [enp0s3]</span></span>
<span class="line"><span>      dhcp4: false</span></span>
<span class="line"><span>      addresses: [192.168.1.162/24]</span></span>
<span class="line"><span>      macaddress: 08:00:27:4b:1d:45</span></span>
<span class="line"><span>      routes:</span></span>
<span class="line"><span>        - to: default</span></span>
<span class="line"><span>          via: 192.168.1.1</span></span>
<span class="line"><span>          metric: 100</span></span>
<span class="line"><span>      nameservers:</span></span>
<span class="line"><span>        addresses: [4.2.2.2]</span></span>
<span class="line"><span>      parameters:</span></span>
<span class="line"><span>        stp: false</span></span>
<span class="line"><span>      dhcp6: false</span></span>
<span class="line"><span>  version: 2</span></span></code></pre></div><p>保存並退出文件。</p><p>注：上述文件的配置是我環境中的，請根據你實際環境替換 IP 地址、網口名稱以及 MAC 地址。</p><p>你可以通過運行 <code>netplan apply</code> 命令應用上述變更。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo netplan apply</span></span></code></pre></div><p>你可以通過如下 <code>ip</code> 命令，驗證網橋 <code>br0</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip add show</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Network-Bridge-br0-ubuntu-linux.png" alt="Network-Bridge-br0-ubuntu-linux"></p><h3 id="_6、啓動-kvm-虛擬機管理器" tabindex="-1">6、啓動 KVM 虛擬機管理器 <a class="header-anchor" href="#_6、啓動-kvm-虛擬機管理器" aria-label="Permalink to “6、啓動 KVM 虛擬機管理器”">​</a></h3><p>當 KVM 安裝完成後，你可以使用圖形管理工具 <code>virt-manager</code> 創建虛擬機。你可以在 GNOME 搜索工具中搜索 <code>Virtual Machine Manager</code> 以啓動。</p><p>點擊搜索出來的圖標即可：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Access-Virtual-Machine-Manager-Ubuntu-Linux.png" alt="Access-Virtual-Machine-Manager-Ubuntu-Linux"></p><p>虛擬機管理器界面如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Virtual-Machine-Manager-Interface-Ubuntu-Linux.png" alt="Virtual-Machine-Manager-Interface-Ubuntu-Linux"></p><p>你可以點擊 “<ruby>文件<rt>File</rt></ruby>” 並選擇 “<ruby>新建虛擬機<rt>New Virtual Machine</rt></ruby>”。你也可以點擊下圖所示的圖標：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/New-Virtual-Machine-Icon-Virt-Manager.png" alt="New-Virtual-Machine-Icon-Virt-Manager"></p><p>在彈出的虛擬機安裝嚮導將看到如下四個選項：</p><ul><li>本地安裝介質（ISO 鏡像或 CDROM）</li><li>網絡安裝（HTTP、HTTPS 和 FTP）</li><li>導入現有磁盤鏡像</li><li>手動安裝</li></ul><p>本文使用已下載的 ISO 鏡像，你可以選擇自己的 ISO 鏡像，選擇第一個選項，並點擊 “<ruby>向前<rt>Forward</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Local-Install-Media-ISO-Virt-Manager.png" alt="Local-Install-Media-ISO-Virt-Manager"></p><p>下一步中，點擊 “<ruby>瀏覽<rt>Browse</rt></ruby>” 選擇 ISO 鏡像位置。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Browse-ISO-File-Virt-Manager-Ubuntu-Linux.png" alt="Browse-ISO-File-Virt-Manager-Ubuntu-Linux"></p><p>在下一個窗口中點擊 “<ruby>瀏覽本地<rt>Browse local</rt></ruby>” 選取本機中 ISO 鏡像。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Browse-Local-ISO-Virt-Manager.png" alt="Browse-Local-ISO-Virt-Manager"></p><p>如下所示，我們選擇了 Debian 11 ISO 鏡像，隨後點擊 “<ruby>打開<rt>Open</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-ISO-File-Virt-Manager.png" alt="Choose-ISO-File-Virt-Manager"></p><p>當 ISO 鏡像選擇後，點擊 “<ruby>向前<rt>Forward</rt></ruby>” 進入下一步。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Forward-after-browsing-iso-file-virt-manager.png" alt="Forward-after-browsing-iso-file-virt-manager"></p><p>接着定義虛擬機所用內存大小以及 CPU 核心數，並點擊 “<ruby>向前<rt>Forward</rt></ruby>” 。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Virtual-Machine-RAM-CPU-Virt-Manager.png" alt="Virtual-Machine-RAM-CPU-Virt-Manager"></p><p>下一步中，輸入虛擬機磁盤空間，並點擊 “<ruby>向前<rt>Forward</rt></ruby>” 繼續。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Storage-for-Virtual-Machine-KVM-Virt-Manager.png" alt="Storage-for-Virtual-Machine-KVM-Virt-Manager"></p><p>如你需要將虛擬機網卡連接至網橋，點擊 “<ruby>選擇網絡<rt>Network selection</rt></ruby>” 並選擇 <code>br0</code> 網橋。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Network-Selection-KVM-Virtual-Machine-Virt-Manager.png" alt="Network-Selection-KVM-Virtual-Machine-Virt-Manager"></p><p>最後，點擊 “<ruby>完成<rt>Finish</rt></ruby>” 按鈕結束設置虛擬機。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Finish-to-OS-Installation-KVM-VM.png" alt="Choose-Finish-to-OS-Installation-KVM-VM"></p><p>稍等片刻，虛擬機的創建過程將開始。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Creating-Domain-Virtual-Machine-Virt-Manager.png" alt="Creating-Domain-Virtual-Machine-Virt-Manager"></p><p>當創建結束時，虛擬機將開機並進入系統安裝界面。如下是 Debian 11 的安裝選項。在這裏你可以根據需要進行系統安裝。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Virtual-Machine-Console-Virt-Manager.png" alt="Virtual-Machine-Console-Virt-Manager"></p><h3 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h3><p>至此，本文向你演示瞭如何在 Ubuntu 22.04 上 安裝 KVM 虛擬化引擎。你的反饋對我們至關重要。</p><hr>`,84)),e("p",null,[a[1]||(a[1]=s("via: ",-1)),i(t,{href:"https://www.linuxtechi.com/how-to-install-kvm-on-ubuntu-22-04/"},{default:n(()=>[...a[0]||(a[0]=[s("https://www.linuxtechi.com/how-to-install-kvm-on-ubuntu-22-04/",-1)])]),_:1})]),e("p",null,[a[6]||(a[6]=s("作者：",-1)),i(t,{href:"https://www.linuxtechi.com/author/james/"},{default:n(()=>[...a[2]||(a[2]=[s("James Kiarie",-1)])]),_:1}),a[7]||(a[7]=s(" 選題：",-1)),i(t,{href:"https://github.com/lkxed"},{default:n(()=>[...a[3]||(a[3]=[s("lkxed",-1)])]),_:1}),a[8]||(a[8]=s(" 譯者：",-1)),i(t,{href:"https://github.com/turbokernel"},{default:n(()=>[...a[4]||(a[4]=[s("turbokernel",-1)])]),_:1}),a[9]||(a[9]=s(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:n(()=>[...a[11]||(a[11]=[s("Linux中國",-1)])]),_:1}),a[14]||(a[14]=s(" 榮譽推出",-1))])])}const V=l(c,[["render",d]]);export{f as __pageData,V as default};
